//! 🧪️ Public reconstruction keeps original blob prefixes and both SQL/native custody.
use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetirementDemand};
use semio_framework_value::native_encoding::{NativeEncodeControl,NativeAllocationEvent,NativeEncodeAllocationIssuer,NativeEncodeConstructionRecipient,NativeEncodeWorkRecipient};
struct Work(u64);impl NativeEncodeWorkRecipient for Work{fn admits(&mut self,_:u64,more:u64)->Result<bool,ValueError>{Ok(more<=self.0)}fn committed(&mut self,actual:u64)->Result<(),ValueError>{self.0-=actual;Ok(())}}
struct Recipient{grant:RetainedCloneGrant,submitted:RetainedCloneProgress,refuse:bool}
impl NativeEncodeConstructionRecipient for Recipient{fn submitted(&self)->RetainedCloneProgress{self.submitted}fn grant(&mut self,_:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(self.grant)}fn accept(&mut self,grant:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{assert_eq!(grant,self.grant);self.submitted=self.submitted.checked_add(progress)?;if self.refuse&&progress.retained_capacity_bytes==0&&progress.copied_bytes!=0{Err(ValueError::literal(ValueRefusalKind::Canceled,"original blob receipt refused"))}else{Ok(())}}}
fn close<T:semio_framework_value::retirement::RetireOwned>(value:T,grant:RetainedCloneGrant){let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(value).ok().unwrap();for _ in 0..65536{if owner.terminal_is_empty(){break}owner.step(grant).unwrap();}assert!(owner.terminal_is_empty());}
#[test]
fn reconstructed_blob_keeps_prefix_and_original_sql_outcome(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️.json")).unwrap();let count=fixture["payloadBytes"].as_u64().unwrap()as usize;let pattern=fixture["pattern"].as_array().unwrap();let source:Vec<u8>=(0..count).map(|i|pattern[i%pattern.len()].as_u64().unwrap()as u8).collect();let g=&fixture["grant"];let grant=RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize};
 for case in fixture["cases"].as_array().unwrap(){
  let name=case["name"].as_str().unwrap();let mut physical=Recipient{grant,submitted:Default::default(),refuse:name=="receipt-refused"};let mut work=Work(8);let mut native_progress=|_|true;let admitted=std::sync::atomic::AtomicUsize::new(0);let mut quoted=None;
  let mut allocation=|event|{match event{NativeAllocationEvent::Admit(request)=>{assert_eq!(request.owned_bytes.checked_add(request.bytes),Some(request.next_owned_bytes));assert!(request.next_owned_bytes<=request.maximum_bytes);},NativeAllocationEvent::Quote(request)=>{assert!(quoted.replace(request).is_none());},NativeAllocationEvent::Post{request,actual}=>{assert_eq!(quoted.take(),Some(request));admitted.fetch_add(actual,std::sync::atomic::Ordering::Relaxed);},NativeAllocationEvent::Cancel(request)=>assert_eq!(quoted.take(),Some(request))};Ok(())};
  let mut allocation_issuer=NativeEncodeAllocationIssuer::new();let mut allocation_loan=allocation_issuer.loan(&mut allocation);let mut native=NativeEncodeControl::new_forwarded(grant.maximum_capacity_bytes,&mut native_progress,&mut allocation_loan);let mut callback=|event:semio_framework_io_sqlite_model::SqliteSnapshotProgress|{if name=="sql-progress-panics"&&event.completed==65536&&event.total==count{panic!("original SQL observer panicked")}true};let limits=semio_framework_io_sqlite_model::SqliteDatabaseLimits{max_allocation_bytes:if name=="sql-denied"{count-1}else{count},..Default::default()};let mut control=SqliteSnapshotControl::new(&mut callback,limits);let mut output=Vec::new();let mut marker=NativeSnapshotEffectProgress::default();let mut unwind=None;let mut stage_unwind=None;let mut allocation_state=semio_framework_io_control::NativeSnapshotAllocation::Encode(Default::default());
  let mut construction_issuer=semio_framework_value::native_encoding::NativeEncodeConstructionIssuer::new();let mut work_issuer=semio_framework_value::native_encoding::NativeEncodeWorkIssuer::new();let mut construction_loan=construction_issuer.loan(&mut physical);let mut work_loan=work_issuer.loan(&mut work);let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||native.with_construction_recipient(&mut construction_loan,|native|native.with_work_recipient(&mut work_loan,|native|{let mut original=semio_framework_io_control::NativeSnapshotEncodeOwner::new(native,grant);let mut owner=SnapshotOwner::Encode(&mut original);let mut reconstruction=super::super::Reconstruction::new(&mut control)?;Ok::<_,ValueError>(reconstruction.blob_into(&mut output,&source,&mut owner,&mut marker,&mut unwind,&mut stage_unwind,&mut allocation_state,1))})).unwrap()));
  assert_eq!(result.is_err(),name=="sql-progress-panics");let stage=match result{Ok(stage)=>stage,Err(_)=>stage_unwind.take().expect("original SQL unwind outcome")};assert_eq!(stage.work,Some(case["work"].as_u64().unwrap()));assert_eq!(output.len(),case["prefix"].as_u64().unwrap()as usize);assert_eq!(output,&source[..output.len()]);assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::from_slice::<serde_json::Value>(&serde_json::to_vec(&source[..output.len()]).unwrap()).unwrap());let expected=if output.capacity()==0{0}else{count};assert_eq!(output.capacity(),expected);assert_eq!(admitted.load(std::sync::atomic::Ordering::Relaxed),expected);assert_eq!(control.allocation_bytes(),expected);close(output,grant);close(stage,grant);close(allocation_state,grant);if let Some(failure)=unwind{close(failure,grant);}
 }
}
